interface DateProvider { LocalDate today(); }

class SeamOrderValidator {
    private final DateProvider dateProvider;
    SeamOrderValidator(DateProvider dateProvider) { this.dateProvider = dateProvider; }

    boolean isExpired(Order order) {
        return order.deadline().isBefore(dateProvider.today());
    }
}
