    private final int newImplementationTrafficPercent; // np. 10, potem 50, potem 100

    double calculateShipping(Order order, int customerId) {
        boolean useNew = (customerId % 100) < newImplementationTrafficPercent;
        return useNew
            ? new ModernShippingCalculator().calculate(order)
            : new LegacyShippingCalculator().calculate(order);
    }
}
